import{_ as t,o as a,c as s,a2 as n}from"./chunks/framework.BZO4qERu.js";const g=JSON.parse('{"title":"Agents / ACP","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/acp.md","filePath":"getting-started/acp.md","lastUpdated":1780941437000}'),o={name:"getting-started/acp.md"};function r(i,e,l,h,c,d){return a(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="agents-acp" tabindex="-1">Agents / ACP <a class="header-anchor" href="#agents-acp" aria-label="Permalink to &quot;Agents / ACP&quot;">​</a></h1><p>Memoh can connect a bot to ACP-compatible coding agents. ACP agents are external coding workflows that can work from the bot&#39;s chat workspace while keeping their sessions separate from normal chat and discuss conversations.</p><p>Current setup examples visible in Memoh include Codex and Claude Code. Treat them as supported setup paths, not as the only possible ACP-compatible agents over time.</p><hr><h2 id="setup-flow" tabindex="-1">Setup Flow <a class="header-anchor" href="#setup-flow" aria-label="Permalink to &quot;Setup Flow&quot;">​</a></h2><ol><li>Open a bot&#39;s <strong>Detail Page</strong>.</li><li>Go to the <strong>Agents</strong> tab.</li><li>Enable the agent you want to use.</li><li>Choose the setup or authentication mode shown by that agent, such as OAuth, API key, or self-managed setup.</li><li>Save the configuration.</li><li>Open the chat workspace and start the enabled agent from there.</li></ol><p>The exact fields depend on the selected agent because each ACP integration owns its own authentication and setup requirements.</p><hr><h2 id="acp-agent-sessions" tabindex="-1">ACP Agent Sessions <a class="header-anchor" href="#acp-agent-sessions" aria-label="Permalink to &quot;ACP Agent Sessions&quot;">​</a></h2><p>ACP work uses the <code>acp_agent</code> session type. These sessions are created and managed by the Agents/ACP workflow.</p><p>They are not created through normal <code>/new chat</code> or <code>/new discuss</code> routing. In the Web UI, you can filter sessions by <code>acp_agent</code> to find coding-agent work separately from everyday conversations.</p><hr><h2 id="attachments" tabindex="-1">Attachments <a class="header-anchor" href="#attachments" aria-label="Permalink to &quot;Attachments&quot;">​</a></h2><p>ACP Agent sessions currently do not support message attachments. Use a normal chat session when you need to send files or images directly to the bot.</p><hr><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="/getting-started/bot.html">Bot Management</a></li><li><a href="/getting-started/sessions.html">Sessions</a></li><li><a href="/getting-started/files.html">Files</a></li></ul>',17)])])}const u=t(o,[["render",r]]);export{g as __pageData,u as default};
